<?php require dirname(__DIR__).'/includes/functions.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); q('UPDATE users SET active=1-active WHERE id=?',[(int)post('id')]); flash('Customer access updated.'); go('admin/customers.php'); }
$title='Customers'; $customer=get('id')?one('SELECT id,full_name,email,username,phone,active FROM users WHERE id=?',[(int)get('id')]):null; require __DIR__.'/_header.php'; ?>
<?php if($customer): ?><div class="glass p-4 mb-4"><h2><?= e($customer['full_name']) ?></h2><p><?= e($customer['email']) ?> · <?= e($customer['phone']) ?></p><h3>Customer orders</h3><?php foreach(all('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC',[$customer['id']]) as $o): ?><a class="summary-row" href="<?= url('admin/orders.php?id='.$o['id']) ?>"><span><?= e($o['order_number']) ?> · <?= e($o['status']) ?></span><strong><?= money($o['total']) ?> ↗</strong></a><?php endforeach; ?></div><?php endif; ?><form method="get" class="search-inline mb-4"><input class="form-control" name="q" value="<?= e(get('q')) ?>" placeholder="Name, email or username" aria-label="Search customers"><button class="btn btn-soft">Search</button></form><div class="glass p-3 table-responsive"><table class="table"><thead><tr><th>Customer</th><th>Email</th><th>Joined</th><th>Access</th><th></th></tr></thead><tbody><?php $term='%'.get('q').'%'; foreach(all('SELECT id,full_name,email,active,created_at FROM users WHERE full_name LIKE ? OR email LIKE ? OR username LIKE ? ORDER BY id DESC',[$term,$term,$term]) as $row): ?><tr><td><a href="<?= url('admin/customers.php?id='.$row['id']) ?>"><?= e($row['full_name']) ?> ↗</a></td><td><?= e($row['email']) ?></td><td><?= e($row['created_at']) ?></td><td><?= $row['active']?'Enabled':'Disabled' ?></td><td><form method="post" data-confirm="Change this customer’s account access?"><?= csrf() ?><input type="hidden" name="id" value="<?= $row['id'] ?>"><button class="btn btn-soft btn-sm"><?= $row['active']?'Disable':'Enable' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__.'/_footer.php'; ?>
